    # We need l2/2 < l1 < 3*l2/4
    lower_bound = l2 / 2.0
    upper_bound = 3 * l2 / 4.0

    possible_l1s = []
    # Iterate through integers between the bounds
    for l1_candidate in range(int(lower_bound) + 1, int(upper_bound) + 1):
        if lower_bound < l1_candidate < upper_bound:
            # To avoid reducible cases like (2,3,4) -> (4,6,8), enforce coprimality.
            # gcd(l1, l2) is a sufficient condition to avoid proportionality to smaller integer solutions.
            if gcd(l1_candidate, l2) == 1:
                possible_l1s.append(l1_candidate)

