la, lb, lc = l1, l2, 2 * l2 - l1

# The core insight is that cos(alpha/2) and cos(beta/2) can be found from an auxiliary triangle with sides la, lb, lc.
# cos(alpha/2) = (lb^2 + lc^2 - la^2) / (2 * lb * lc)
# We can use a simplified formula derived in the analysis.
# cos(alpha/2) = (5*l2 - 4*l1) / (2 * (2*l2 - l1))
cos_half_alpha_num = 5 * l2 - 4 * l1
cos_half_alpha_den = 2 * (2 * l2 - l1)

# cos(alpha) = 2*cos^2(alpha/2) - 1
num = 2 * cos_half_alpha_num**2 - cos_half_alpha_den**2
den = cos_half_alpha_den**2

# The problem guarantees cos(alpha) is positive, which we've verified in the design phase.
if num <= 0:
    return False, None

# Reduce the fraction
common_divisor = gcd(num, den)
p = num // common_divisor
q = den // common_divisor

answer = p + q
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

